// The app's density stamp, moved out of index.html so the guest CSP needs no inline script. (Generated by scripts/build-join-site-app.js.)
(function () {
        var density = localStorage.getItem("flowjoe_density") || "compact";
        if (density === "compact" || density === "dense") document.body.classList.add("density-" + density);
        var surfaceStyle = localStorage.getItem("flowjoe_surface_style") || "filled";
        if (surfaceStyle === "filled") document.body.classList.add("shape-soft");
      })();
